import http.client,json,os,signal,socket,ssl,time,urllib.parse,urllib.request

def retire(api,case):
    # ResourceVersion protects healthy peers and concurrent edits.
    for _ in range(6):
        code,old=api('GET',case['endpoints_path']);assert code==200
        changed=False
        for subset in old.get('subsets',[]):
            for key in ('addresses','notReadyAddresses'):
                values=subset.get(key,[]);remaining=[a for a in values if a['ip']!=case['retiring_address']]
                changed=changed or len(remaining)!=len(values)
                if key in subset:subset[key]=remaining
        if not changed:break
        code,_=api('PUT',case['endpoints_path'],old)
        if code==200:break
        if code!=409:raise RuntimeError('Withdrawal API failed')
    else:raise RuntimeError('Concurrent endpoint updates did not settle')
    until=time.monotonic()+case['observation_seconds'];confirmed=0
    while time.monotonic()<until:
        code,page=api('GET',case['slice_path']);assert code==200
        addresses={ip for s in page['items'] if s['metadata'].get('labels',{}).get('kubernetes.io/service-name')==case['service_name'] for e in s.get('endpoints',[]) for ip in e['addresses']}
        opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
        with opener.open(case['proxy_state_url'],timeout=1) as response:state=json.load(response)
        applied=state.get('services',{}).get(case['proxy_service_name'],{}).get('loadBalancer',{}).get('servers',[])
        urls={server['url'] for server in applied}
        if case['retiring_address'] not in addresses and case['healthy_address'] in addresses and urls=={case['healthy_backend_url']}:
            context=ssl.create_default_context(cafile=case['ca'])
            with context.wrap_socket(socket.create_connection(('127.0.0.1',case['gateway_port']),timeout=1),server_hostname=case['server_name']) as sock:
                sock.settimeout(1);sock.sendall(('GET /proof HTTP/1.1\r\nHost: '+case['server_name']+'\r\nConnection: close\r\n\r\n').encode());response=http.client.HTTPResponse(sock);response.begin();body=response.read().decode()
                confirmed=confirmed+1 if response.status==200 and body==case['healthy_receipt'] else 0
            if confirmed>=3:
                os.kill(case['retiring_pid'],signal.SIGTERM)
                return
        time.sleep(.025)
    raise RuntimeError('Actual endpoint/Ingress propagation did not converge before deadline')

